css:
@page {
  size: A4;
  margin: 7mm;
}

:root {
  --brand: #0f766e;
  --ink: #111827;
  --muted: #5f6b76;
  --line: #cfd8df;
  --soft: #e7f4f2;
  --soft2: #f7fbfa;
}

body {
  font-family: "Ubuntu", "Segoe UI", Arial, sans-serif;
  font-size: 8.5px;
  color: var(--ink);
}

.print-format {
  padding: 0 !important;
  margin: 0 !important;
}

* {
  box-sizing: border-box;
}

.po-shell {
  width: 100%;
}

.po-sheet {
  width: 100%;
  background: #fff;
}

/* Header */
.header-table {
  width: 100%;
  border-collapse: collapse;
  table-layout: fixed;
  border-bottom: 1px solid var(--line);
  margin-bottom: 5px;
}

.header-table td {
  border: 0 !important;
  vertical-align: top !important;
  padding: 0 0 5px 0 !important;
}

.company-left {
  width: 38%;
  line-height: 1.35;
}

.company-name {
  font-size: 13px;
  font-weight: 700;
  color: #000;
  margin-bottom: 3px;
}

.logo-center {
  width: 24%;
  text-align: center;
}

.company-logo {
  max-width: 135px !important;
  max-height: 78px !important;
  width: auto !important;
  height: auto !important;
  object-fit: contain;
}

.logo-fallback {
  display: inline-block;
  font-size: 22px;
  font-weight: 700;
  color: var(--brand);
  border: 1px solid var(--line);
  padding: 12px 18px;
}

.po-title {
  margin-top: 3px;
  font-size: 15px;
  font-weight: 700;
  color: var(--brand);
  letter-spacing: 0.04em;
}

.meta-right {
  width: 38%;
}

.meta-table {
  width: 100%;
  border-collapse: collapse;
}

.meta-table td {
  border: 1px solid var(--line) !important;
  padding: 3px 5px !important;
  line-height: 1.2;
}

.meta-table td:first-child {
  width: 38%;
  background: var(--soft);
  color: var(--brand);
  font-weight: 600;
}

.meta-table td:last-child {
  font-weight: 600;
  text-align: right;
}

/* Party */
.party-table {
  width: 100%;
  border-collapse: collapse;
  table-layout: fixed;
  margin-bottom: 5px;
}

.party-table > tbody > tr > td {
  vertical-align: top !important;
  border: 0 !important;
  padding: 0 !important;
}

.party-card {
  width: 49%;
  border-top: 1px solid var(--line) !important;
  padding-top: 4px !important;
}

.gap {
  width: 2%;
}

.section-title {
  color: var(--brand);
  font-weight: 700;
  font-size: 8px;
  text-transform: uppercase;
  letter-spacing: 0.03em;
  margin-bottom: 3px;
}

.party-name {
  font-size: 10px;
  font-weight: 700;
  margin-bottom: 3px;
}

.info-table {
  width: 100%;
  border-collapse: collapse;
  table-layout: fixed;
}

.info-table td {
  border: 1px solid var(--line) !important;
  padding: 2.5px 4px !important;
  line-height: 1.2;
  vertical-align: top !important;
}

.info-table td:first-child {
  width: 28%;
  background: var(--soft2);
  color: var(--muted);
  font-weight: 600;
}

.info-table td:last-child {
  word-break: break-word;
}

/* Items */
.section-box {
  border-top: 1px solid var(--line);
  padding-top: 4px;
  margin-bottom: 5px;
}

.items-table {
  width: 100%;
  border-collapse: collapse;
  table-layout: fixed;
}

.items-table th,
.items-table td {
  border: 1px solid var(--line) !important;
  padding: 3px 4px !important;
  vertical-align: top !important;
  line-height: 1.18;
}

.items-table thead th {
  background: var(--soft);
  color: var(--brand);
  font-size: 7.5px;
  font-weight: 700;
  text-align: center;
}

.num {
  text-align: right;
  direction: ltr;
  white-space: nowrap;
}

.center {
  text-align: center;
}

.muted {
  color: var(--muted);
  font-size: 7.5px;
  margin-top: 1px;
}

/* Totals */
.total-layout {
  width: 100%;
  border-collapse: collapse;
  table-layout: fixed;
  margin-top: 4px;
  margin-bottom: 4px;
}

.total-layout > tbody > tr > td {
  border: 0 !important;
  padding: 0 !important;
  vertical-align: top !important;
}

.tax-box,
.totals-box {
  width: 49%;
  border-top: 1px solid var(--line) !important;
  padding-top: 4px !important;
}

.small-table,
.totals-table {
  width: 100%;
  border-collapse: collapse;
}

.small-table th,
.small-table td,
.totals-table td {
  border: 1px solid var(--line) !important;
  padding: 3px 4px !important;
  line-height: 1.2;
}

.small-table th {
  background: var(--soft2);
  color: var(--brand);
  font-weight: 700;
}

.totals-table td:first-child {
  color: var(--muted);
  font-weight: 600;
}

.grand-row td {
  background: var(--brand);
  color: #fff !important;
  font-weight: 700 !important;
}

/* In words */
.in-words {
  border: 1px dashed var(--line);
  padding: 4px 5px;
  margin: 5px 0;
  color: var(--muted);
  line-height: 1.3;
}

/* Terms matching your image */
.terms-box {
  border: 1px solid #222;
  padding: 6px 6px 10px 6px;
  margin-top: 6px;
  min-height: 390px;
  page-break-inside: avoid;
}

.terms-title {
  font-size: 10px;
  font-weight: 800;
  text-transform: uppercase;
  letter-spacing: 0.03em;
  margin-bottom: 6px;
  color: #111;
}

.terms-content {
  font-size: 8.4px;
  line-height: 1.25;
  color: #111;
}

.terms-content .ql-editor {
  padding: 0 !important;
}

.terms-content h1,
.terms-content h2,
.terms-content h3 {
  font-size: 9.4px !important;
  font-weight: 800 !important;
  text-transform: uppercase;
  margin: 8px 0 4px 0 !important;
  padding: 0 !important;
  line-height: 1.15 !important;
}

.terms-content p {
  margin: 0 0 2px 0 !important;
  padding: 0 !important;
}

.terms-content br {
  display: none;
}

.terms-content div {
  line-height: 1.25;
}

/* Signature */
.signature-table {
  width: 100%;
  border-collapse: collapse;
  margin-top: 12px;
  page-break-inside: avoid;
}

.signature-table td {
  width: 33.33%;
  text-align: center;
  border: 0 !important;
  padding: 14px 12px 0 12px !important;
  color: var(--muted);
}

.sign-line {
  border-top: 1px solid #333;
  margin-bottom: 4px;
}

/* PDF safety */
.header-table,
.party-table,
.total-layout,
.in-words,
.signature-table {
  page-break-inside: avoid;
}

.items-table tr {
  page-break-inside: avoid;
}
